mapper.select:
SELECT p.id, p.title, p.content, p.user_id as author_id, p.views, p.likes, p.comment_count, p.status, p.topic_id, p.images, p.created_at, u.nickname as author_name, t.title as topic_name FROM posts p LEFT JOIN users u ON p.user_id = u.id LEFT JOIN topics t ON p.topic_id = t.id WHERE 1=1
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
AND p.topic_id = #{topicId}
ORDER BY p.created_at DESC
